sealed class State {
    object Loading : State()
    data class Ready(val n: Int) : State()
}

fun render(s: State) = when (s) {
    is State.Loading if s.isBusy -> "loading"   // guard — NOT exhaustiveness
    is State.Ready -> "ready ${s.n}"
    // ERROR: 'when' must be exhaustive — Loading has no uncovered branch
    // but the guard means the compiler can't prove Loading is covered
}

// exhaustive without guards:
fun fine(s: State) = when (s) {
    is State.Loading -> "loading"
    is State.Ready -> "ready ${s.n}"
}

